// Stats come from the query; the AI text is optional (the report goes out without it).
const stats = $('Sales of the last 7 days').item.json;
const summary = $json?.candidates?.[0]?.content?.parts?.map((p) => p.text).join('').trim();
const money = (amount) => new Intl.NumberFormat('es-CO', { style: 'currency', currency: stats.currency, minimumFractionDigits: 0 }).format(amount);

const cards = [
  ['Pedidos', stats.orders],
  ['Aprobados', stats.approved],
  ['Por revisar', stats.to_review],
  ['Esperando pago', stats.awaiting_payment],
  ['Perdidos', stats.lost],
]
  .map(([label, value]) => `<td align="center" style="padding:8px 14px"><div style="font-size:22px"><b>${value}</b></div><div style="color:#666">${label}</div></td>`)
  .join('');

const top = stats.top_products.length
  ? `<ol>${stats.top_products.map((p) => `<li>${p.name} — ${p.quantity} und.</li>`).join('')}</ol>`
  : '<p>Sin ventas esta semana.</p>';

const html = `<p>Hola ${stats.seller_name},</p>
<p>Así le fue a tu tienda en Libra en los últimos 7 días:</p>
<table style="border-collapse:collapse" border="1"><tr>${cards}</tr></table>
<p>Ingresos aprobados: <b>${money(stats.revenue)}</b></p>
<h3>Más vendidos</h3>${top}
${summary ? `<h3>💡 Resumen</h3><p>${summary}</p><p style="color:#888;font-size:12px">Resumen generado con IA a partir de tus números.</p>` : ''}
<p style="color:#666">Reporte automático de Libra.</p>`;

return { json: { to: stats.seller_email, subject: `📊 Tu semana en Libra: ${stats.orders} pedidos, ${money(stats.revenue)} aprobados`, html, has_ai_summary: Boolean(summary) } };
